/*
 * Pro tips
 * - Use two pointers: characters outside [left, right] are already in final position.
 * - Swap both ends, then move both pointers inward; stop when they meet or cross.
 * - Check empty, odd-length, and even-length strings. Java char swaps operate on UTF-16 units, not full Unicode graphemes.
 * - Complexity: O(n) time and O(n) space for the char array and returned string.
 */

import java.util.Scanner;

class Solution {
    public static String reverseString(String s) {
        char[] chars = s.toCharArray();
        int left = 0;
        int right = chars.length - 1;
        while (left < right) {
            char temp = chars[left];
            chars[left] = chars[right];
            chars[right] = temp;
            left++;
            right--;
        }
        return new String(chars);
    }

    public static void main(String[] args) {
        java.util.Scanner scanner = new java.util.Scanner(System.in);
        String s = scanner.nextLine();
        scanner.close();
        String res = reverseString(s);
        System.out.println(res);
    }
}
